return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Shkoni te &quot;Kërkimi i shtojcave&quot;.','Activate %s' => 'Aktivizo %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> kërkon që <strong>%2$s</strong> të instalohet dhe aktivizohet. <a href="%4$s">%3$s</a>','Enter your code here' => 'Shkruani kodin tuaj këtu','Add %s' => 'Shto %s','Remove' => 'Hiq','Order number and receipt will be sent to this email address.' => 'Numri i porosisë dhe fatura do të dërgohen në këtë adresë emaili.','Apartment, unit, building, floor, etc.' => 'Apartament, njesi, pallat, kat etj.','Shipping phone' => 'Telefoni i transportit','Only used for shipping-related questions.' => 'Përdoret vetëm për pyetje të lidhura me transportin.','Single step' => 'Një hap i vetëm','Click to go to the order summary' => 'Klikoni për të shkuar te përmbledhja e porosisë','Cart total:' => 'Totali i karrocave:','Proceed to %s' => 'Vazhdoni te %s','Proceed to contact' => 'Vazhdoni të kontaktoni','Proceed to shipping' => 'Vazhdoni te transporti','Proceed to billing' => 'Vazhdoni te faturimi','Proceed to payment' => 'Vazhdoni te pagesa','Shipping method' => 'Mënyra e transportit','Additional notes' => 'Shënime shtesë','Payment method' => 'Mënyra e pagesës','Step %1$s of %2$s' => 'Hapi %1$s nga %2$s','Change: %s' => 'Ndryshimi: %s','Not selected yet.' => 'Nuk është zgjedhur ende.','Same as shipping address' => 'Njësoj si adresa e transportit','Same as billing address' => 'Njësoj si adresa e faturimit','Order summary' => 'Përmbledhja e porosisë','Edit cart' => 'Redakto karrocën','Did you mean %s?' => 'E kishit fjalën %s?','Change email address to: {suggestion-value}' => 'Ndrysho adresën e emailit në: {suggestion-value}','This is a required field.' => 'Kjo është një fushë e detyrueshme.','This is not a valid email address.' => 'Kjo nuk është një adresë e vlefshme emaili.','This field does not match the related field value.' => 'Kjo fushë nuk përputhet me vlerën e fushës përkatëse.','The CPF number "{cpf_number}" is invalid.' => 'Numri CPF &quot;{cpf_number}&quot; është i pavlefshëm.','The CNPJ number "{cnpj_number}" is invalid.' => 'Numri CNPJ &quot;{cnpj_number}&quot; është i pavlefshëm.','(Required)' => '(E detyrueshme)','Checkout Header - Desktop' => 'Kreu i arkës - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Shfaq miniaplikacionet në kokën e arkës për ekrane të mëdha. Shfaqet vetëm nëse përdorni titullin e blerjes së shtojcës.','Checkout Header - Mobile' => 'Kreu i arkës - celular','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Shfaq miniaplikacionet poshtë kokës së arkës për pajisjet celulare. Shfaqet vetëm nëse përdorni titullin e blerjes së shtojcës.','Checkout Sidebar' => 'Shiriti anësor i blerjes','Display widgets on the checkout sidebar after the order summary.' => 'Shfaqni miniaplikacionet në shiritin anësor të arkës pas përmbledhjes së porosisë.','Checkout Order Summary' => 'Përmbledhja e porosisë së arkëtimit','Display widgets inside the order summary at the checkout page.' => 'Shfaqni miniaplikacionet brenda përmbledhjes së porosisë në faqen e arkëtimit.','Checkout Below Place Order' => 'Blini poshtë porosisë','Display widgets below the place order button at the checkout page.' => 'Shfaqni miniaplikacionet poshtë butonit të rendit të vendit në faqen e blerjes.','Checkout Footer' => 'Fundi i përfundimit të blerjes','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Shfaq miniaplikacionet në fundin e arkës. Shfaqet vetëm nëse përdorni fundin e përfundimit të blerjes së shtojcës.','Classic' => 'Klasike','Boxed' => 'Në kuti','Split' => 'Ndarë','Minimalist' => 'Minimaliste','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Shtojcat e Fluid Checkout dhe Data e Dorëzimit nga CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Zbuluam se po përdorni shtojcat Koha e datës së dorëzimit dhe marrjes për WooCommerce (falas dhe PRO) nga CodeRockz. Integrimi me këto shtojca është zhvendosur në Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Përmirësojeni në PRO','Fluid Checkout database updated successfully' => 'Baza e të dhënave Fluid Checkout u përditësua me sukses','The database changes where applied successfully.' => 'Baza e të dhënave ndryshon kur zbatohet me sukses.','Dismiss' => 'Largoje','Fluid Checkout database update' => 'Përditësimi i bazës së të dhënave të Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Kërkohen disa ndryshime në bazën e të dhënave. Ashtu si me çdo përditësim, ne ju rekomandojmë të <strong>bëni një kopje rezervë të plotë të faqes suaj të internetit përpara se të vazhdoni</strong> .','Update database' => 'Përditëso bazën e të dhënave','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nuk është në përputhje me paraqitjen e arkave të Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout ka nevojë për formularin klasik të arkëtimit të bazuar në kode të shkurtra WooCommerce për të funksionuar. Kur përdorni Divi Builder për të personalizuar pamjen dhe ndjesinë e faqes së arkës, kodet e shkurtra klasike zëvendësohen me miniaplikacione të personalizuara nga Divi Builder për secilën pjesë të faqes së arkës. Këto miniaplikacione të personalizuara nuk janë të përputhshme me Fluid Checkout.</p><p> Ju lutemi modifikoni faqen tuaj të arkës duke zëvendësuar miniaplikacionet e Divi Builder me një miniaplikacion teksti që përmban kodin e shkurtër <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Redakto faqen e arkës','Read the documentation.' => 'Lexoni dokumentacionin.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Funksioni i gjermanizuar i blerjes me shumë hapa PRO duhet të çaktivizohet kur përdorni Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kur përdorni Fluid Checkout, veçoria me shumë hapa nga shtojca e gjermanizuar PRO bëhet e panevojshme dhe mund të shkaktojë <strong>gabime kritike gjatë përpunimit të porosive të reja</strong> . Ju lutemi çaktivizoni funksionin e blerjes me shumë hapa PRO të gjermanizuar në cilësimet e shtojcave.','Go to Germanized settings' => 'Shkoni te cilësimet e gjermanizuara','Thanks for choosing Fluid Checkout!' => 'Faleminderit që zgjodhët Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Ju keni përdorur shtojcën për një kohë tani. Si ju duket deri tani?<br> Ju lutemi na jepni një vlerësim të shpejtë, ne vlerësojmë çdo koment dhe na inkurajon të vazhdojmë të përmirësojmë shtojcën :)','Rate the plugin' => 'Vlerësoni shtojcën','I need help!' => 'Unë kam nevojë për ndihmë!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Disa veçori të WooCommerce Checkout Manager nga Quadlayers mund të mos funksionojnë siç pritej kur e përdorni atë me Fluid Checkout. Lexoni <a href="%s">dokumentacionin tonë</a> për më shumë informacion dhe zgjidhje alternative.','Read documentation' => 'Lexoni dokumentacionin','Don\'t show this again' => 'Mos e shfaq më këtë','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Më shumë shabllone dizajni','Optimized cart page' => 'Faqja e optimizuar e karrocave','Optimized order received / thank you page' => 'Porosia e optimizuar e pranuar / faqe falenderimi','Edit cart contents at checkout page' => 'Redakto përmbajtjen e karrocës në faqen e arkës','Account matching / user matching' => 'Përputhja e llogarisë / përputhje e përdoruesit','Trust symbols on the cart and thank you pages' => 'Simbolet e besimit në faqet e karrocave dhe falenderimeve','More positions for the coupon code on the checkout page' => 'Më shumë pozicione për kodin e kuponit në faqen e arkës','International phone numbers' => 'Numrat e telefonit ndërkombëtar','Gift messages and packing slips' => 'Mesazhe dhuratash dhe fletë paketimi','Local pickup and in-store collection' => 'Marrja lokale dhe grumbullimi në dyqan','EU-VAT Assistant' => 'Asistent EU-TVSH','I already have it – Hide this offer' => 'Unë tashmë e kam atë - Fshihe këtë ofertë','Activated' => 'Aktivizuar','Address book' => 'Libri i adresave','Select an image' => 'Zgjidhni një imazh','Cart layout' => 'Paraqitja e karrocave','Cart optimizations' => 'Optimizimi i karrocave','Enable cart page optimizations' => 'Aktivizo optimizimin e faqeve të karrocave','Header and footer template' => 'Shablloni i kokës dhe këmbës','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrollon nëse do të përdoret titulli dhe fundi i faqes pa shpërqendrim ose do të ruhet titulli dhe fundi i temës aktualisht aktive.','Distraction free header and footer' => 'Koka dhe fundi pa shpërqendrim','Theme\'s header and footer' => 'Koka dhe fundi i temës','Cart elements' => 'Elementet e karrocës','Make the order summary stay visible on the cart page while scrolling' => 'Bëje që përmbledhja e porosisë të qëndrojë e dukshme në faqen e karrocës gjatë lëvizjes','Coupon codes' => 'Kodet e kuponit','Hidden' => 'I fshehur','Before the cart items section' => 'Përpara seksionit të artikujve të karrocave','Inside the cart items section' => 'Brenda seksionit të artikujve të karrocave','After the cart items section' => 'Pas seksionit të artikujve të karrocave','Before the shipping section' => 'Përpara seksionit të transportit','After the shipping section' => 'Pas seksionit të transportit','Before the order summary' => 'Para përmbledhjes së porosisë','Inside the order summary' => 'Brenda përmbledhjes së porosisë','Before the order totals' => 'Përpara se porosia të arrijë totalin','After the order totals' => 'Pas totalit të porosisë','After the order summary' => 'Pas përmbledhjes së porosisë','Shipping' => 'Transporti','Select position where to display the shipping costs and calculator on the cart page.' => 'Zgjidhni pozicionin ku të shfaqen kostot e transportit dhe kalkulatori në faqen e karrocës.','Display as a cart section' => 'Shfaq si seksion karroce','Cross-sells' => 'Ndër-shitet','Select position where to display the cross-sells section on the cart page.' => 'Zgjidhni pozicionin ku të shfaqet seksioni i shitjeve të kryqëzuara në faqen e karrocës.','Before the cart actions' => 'Para veprimeve të karrocës','After the cart actions' => 'Pas veprimeve të karrocave','Layout of cross-sell items on the cart page.' => 'Paraqitja e artikujve të shitjes së kryqëzuar në faqen e shportës.','Optimized horizontal cross-sells layout' => 'Paraqitje e optimizuar e ndër-shitjeve horizontale','Theme\'s cross-sells layout' => 'Paraqitja e ndërthurjes së temës','Number of cross-sell items to display on the cart page' => 'Numri i artikujve të kryqëzuar për t&#39;u shfaqur në faqen e karrocës','Add widget areas to the cart page' => 'Shtoni zonat e miniaplikacioneve në faqen e shportës','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Këto zona miniaplikacioni përdoren për të shtuar simbole besimi dhe distinktivë besimi në faqen e karrocave.','Checkout' => 'Përfundimi','Checkout layout' => 'Paraqitja e arkës','Design template' => 'Modeli i dizajnit','Dark mode' => 'Modaliteti i errët','Enable dark mode' => 'Aktivizo modalitetin e errët','Logo image' => 'Imazhi i logos','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Zgjidhni një imazh që do të shfaqet në kokën e faqes së arkës. Zbatohet vetëm kur përdorni kokën dhe fundin pa shpërqendrim.','Header background color' => 'Ngjyra e sfondit të kokës','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Zgjidhni një ngjyrë sfondi për kokën e faqes së arkës. Zbatohet vetëm kur përdorni kokën dhe fundin pa shpërqendrim.','HTML color value. ie: #f3f3f3' => 'Vlera e ngjyrës HTML. dmth: #f3f3f3','Page background color' => 'Ngjyra e sfondit të faqes','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Zgjidhni një ngjyrë sfondi për faqen e arkës. Ngjyra aplikohet në elementin <em>e trupit</em> .','Footer background color' => 'Ngjyra e sfondit të fundit','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Zgjidhni një ngjyrë sfondi për fundin e faqes së arkës. Zbatohet vetëm kur përdorni kokën dhe fundin pa shpërqendrim.','Progress bar' => 'Shiriti i progresit','Display the checkout progress bar when using multi-step checkout layout' => 'Shfaq shiritin e progresit të arkëtimit kur përdorni paraqitjen e arkëtimit me shumë hapa','Make the checkout progress bar stay visible while scrolling' => 'Bëje shiritin e progresit të arkëtimit të qëndrojë i dukshëm gjatë lëvizjes','Express checkout' => 'Arkë e shpejtë','Enable the express checkout section' => 'Aktivizo seksionin e blerjes së shpejtë','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Shfaq seksionin e pagesës së shpejtë në përfundim të blerjes kur portat e pagesave të mbështetura e kanë të aktivizuar këtë veçori.','Display express checkout buttons in one line for larger screens' => 'Shfaqni butonat e arkëtimit të shpejtë në një rresht për ekrane më të mëdha','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Injoroni fushat shtesë të kërkuara për arkëtimet kur paguani me një portë pagese të përputhshme për arkëtim të shpejtë','Make the order summary stay visible while scrolling' => 'Bëje që përmbledhja e porosisë të qëndrojë e dukshme gjatë lëvizjes','Choose a background color for the order summary section.' => 'Zgjidhni një ngjyrë sfondi për seksionin e përmbledhjes së porosisë.','Highlight the order totals row in the order summary table' => 'Theksoni rreshtin totale të porosive në tabelën përmbledhëse të porosive','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Më e dobishme kur seksioni i përmbledhjes së porosisë nuk ka një ngjyrë të theksuar të sfondit. Mund të zbatohet gjithashtu për faqet e karrocave, porosive të marra dhe shikimit të porosive kur përdorni Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Lidhja e veprimit në përmbledhjen e porosisë në arkë.','Edit cart link' => 'Redakto lidhjen e karrocës','Cart items count' => 'Artikujt e karrocave numërohen','Link to shop page' => 'Lidhja me faqen e dyqanit','Cart items' => 'Artikujt e karrocave','Hide cart items errors at the checkout page' => 'Fshih gabimet e artikujve të karrocës në faqen e arkës','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Mos shfaq mesazhin e gabimeve të artikujve të karrocës në krye të faqes së arkës. Kur dorëzoni formularin e arkës për të përfunduar blerjen, këto mesazhe gabimi do të shfaqen gjithmonë.','Place order' => 'Vendos porosinë','Define the position to display "Place order" and terms checkbox section.' => 'Përcaktoni pozicionin për të shfaqur seksionin e kutisë së kontrollit &quot;Vendosni porosinë&quot; dhe termat.','Some options might not be compatible with some plugins and themes.' => 'Disa opsione mund të mos jenë të pajtueshme me disa shtojca dhe tema.','Below the payment section' => 'Nën seksionin e pagesave','Below the order summary' => 'Më poshtë përmbledhjen e porosisë','Both below the payment section and the order summary' => 'Si poshtë seksionit të pagesës ashtu edhe përmbledhja e porosisë','Add widget areas to the checkout page' => 'Shtoni zonat e miniaplikacioneve në faqen e arkëtimit','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Këto zona miniaplikacioni përdoren për të shtuar simbole besimi dhe distinktivë besimi në faqen e arkës.','Display the coupon codes section title' => 'Shfaq titullin e seksionit të kodeve të kuponit','Select position where to display the coupon codes section on the checkout page.' => 'Zgjidhni pozicionin ku të shfaqet seksioni i kodeve të kuponit në faqen e arkës.','Before the checkout steps' => 'Përpara hapave të arkës','As a substep before payment methods' => 'Si një nën-hap përpara mënyrave të pagesës','As a substep after payment methods' => 'Si një nën-hap pas mënyrave të pagesës','Default button style' => 'Stili i parazgjedhur i butonit','"Add" link button' => 'Butoni i lidhjes &quot;Shto&quot;.','Checkout fields' => 'Fushat e blerjes','Optional fields' => 'Fushat opsionale','Hide optional fields behind a link button' => 'Fshihni fushat opsionale pas një butoni lidhjeje','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Rekomandohet ta mbani këtë opsion të kontrolluar për të zvogëluar numrin e fushave të hapura të hyrjes, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">lexoni kërkimin</a> .','Do not hide "Address line 2" fields behind a link button' => 'Mos i fshihni fushat &quot;Rreshti i adresës 2&quot; pas një butoni lidhjeje','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Rekomandohet vetëm kur shumica e klientëve kanë nevojë për fushën &quot;Rreshti i adresës 2&quot; ose kur marrja e adresës së duhur të transportit është thelbësore (d.m.th. nëse dërgoni ushqime dhe produkte të tjera që prishen).','Billing address' => 'Adresa e faturimit','Select position where to display the billing address section on the checkout page.' => 'Zgjidhni pozicionin ku të shfaqet seksioni i adresës së faturimit në faqen e arkës.','As a step before shipping' => 'Si një hap përpara transportit','As a sub-step before the shipping address section' => 'Si një nën-hap përpara seksionit të adresës së transportit','As a sub-step after the shipping address section' => 'Si një nën-hap pas seksionit të adresës së transportit','As a step after shipping' => 'Si një hap pas transportit','As a sub-step before the payment section' => 'Si një nën-hap përpara seksionit të pagesës','Force billing and shipping addresses to the same (single section)' => 'Detyroni adresat e faturimit dhe dërgesës në të njëjtën (seksion i vetëm)','Checkbox for "Same as shipping/billing address" checked by default' => 'Kutia e zgjedhjes për &quot;E njëjtë me adresën e dërgesës/faturimit&quot; e zgjedhur si parazgjedhje','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Kutia e zgjedhjes &quot;E njëjtë me adresën e dërgesës&quot; do të fillojë si e zgjedhur si parazgjedhje kur të shfaqet së pari seksioni i adresës së transportit.<br> Kutia e zgjedhjes &quot;E njëjtë me adresën e faturimit&quot; do të fillojë si e zgjedhur si parazgjedhje kur të shfaqet së pari seksioni i adresës së faturimit.<br> Rekomandohet ta lini këtë opsion të kontrolluar për të reduktuar ndjeshëm numrin e fushave të hapura të hyrjes në arkë, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">lexoni kërkimin</a> .','Highlight the billing address section in the checkout form' => 'Theksoni seksionin e adresës së faturimit në formularin e arkës','Shipping address' => 'Adresa e transportit','Highlight the shipping address section in the checkout form' => 'Theksoni seksionin e adresës së transportit në formularin e arkëtimit','Shipping methods' => 'Metodat e transportit','Choose in which position to display the shipping methods section.' => 'Zgjidhni në cilin pozicion do të shfaqet seksioni i metodave të transportit.','Before shipping address' => 'Adresa para dërgimit','After shipping address' => 'Adresa pas dërgimit','Local pickup' => 'Marrje lokale','Removes shipping address section when a local pickup shipping method is selected.' => 'Heq seksionin e adresës së dërgesës kur zgjidhet një metodë transporti lokale e marrjes.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Zëvendëson adresën e transportit me vendndodhjen e pikës së marrjes kur zgjidhet një metodë transporti lokale e marrjes.','Choose which address to save as the shipping address for local pickup orders.' => 'Zgjidhni adresën që të ruani si adresë transporti për porositë lokale të marrjes.','Save the selected pickup location' => 'Ruani vendndodhjen e zgjedhur të marrjes','Save same as the billing address' => 'Ruani njësoj si adresën e faturimit','Do not save any shipping address' => 'Mos ruani asnjë adresë transporti','Company name field for shipping address' => 'Fusha e emrit të kompanisë për adresën e transportit','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Ndryshoni dukshmërinë për fushën e emrit të kompanisë për seksionin e adresës së transportit në formularin e arkës.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Nëse fusha është caktuar si &quot;opsionale&quot;, e cila është gjendja e parazgjedhur e dukshmërisë, nuk do të zbatohen ndryshime për të lejuar shtojcat e tjera të aplikojnë çdo ndryshim që u nevojitet.','Hidden (remove field)' => 'I fshehur (hiq fushën)','Optional' => 'Fakultative','Required' => 'E detyrueshme','Add shipping phone field to the checkout form.' => 'Shtoni fushën e telefonit të transportit në formularin e arkës.','Choose in which step to display the shipping phone field.' => 'Zgjidhni në cilin hap do të shfaqet fusha e telefonit të transportit.','Contact step' => 'Hapi i kontaktit','Billing phone' => 'Telefoni i faturimit','Add billing phone field to the checkout form.' => 'Shtoni fushën e telefonit të faturimit në formularin e arkës.','Choose in which step to display the billing phone field.' => 'Zgjidhni në cilin hap do të shfaqet fusha e telefonit të faturimit.','Show country code beside the flag' => 'Shfaq kodin e shtetit pranë flamurit','Show an example of a valid phone number inside phone fields' => 'Trego një shembull të një numri telefoni të vlefshëm brenda fushave të telefonit','Do not change placeholders' => 'Mos ndryshoni mbajtësit e vendeve','Show if not defined' => 'Trego nëse nuk është përcaktuar','Always show' => 'Gjithmonë tregoni','Order notes' => 'Porosit shënime','Define the visibility of the additional order notes field.' => 'Përcaktoni dukshmërinë e fushës së shënimeve shtesë të porosive.','Gift options' => 'Opsionet e dhuratave','Allow customers to add a gift message and other gift related options to the order.' => 'Lejo klientët të shtojnë një mesazh dhuratë dhe opsione të tjera të lidhura me dhuratat në porosi.','Display the gift message as part of the order details table instead of a separate section' => 'Shfaqni mesazhin e dhuratës si pjesë e tabelës së detajeve të porosisë në vend të një seksioni të veçantë','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ky opsion ndikon në faqen e konfirmimit të porosisë (faqen e falenderimeve) dhe detajet e porosisë në faqet e llogarisë, emailet dhe fletët e paketimit.','Account matching' => 'Përputhja e llogarisë','Enable the account matching feature' => 'Aktivizo funksionin e përputhjes së llogarisë','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Lidhni porositë e klientit mysafir me llogarinë e tyre ekzistuese kur një llogari ekziston tashmë me detajet e kontaktit të klientit.','Display message when an account exists with the email address provided' => 'Shfaq mesazhin kur ekziston një llogari me adresën e dhënë të emailit','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Zëvendëson fushat e krijimit të llogarisë me një njoftim dhe opsion për t&#39;u identifikuar. Në disa kontekste, mund të rekomandohet ta lini këtë opsion të çaktivizuar për të mbrojtur privatësinë e klientëve.','Dashboard' => 'Paneli','Integrations' => 'Integrimet','License keys' => 'Çelësat e licencës','Visit our website for more information about our plugins and add-ons.' => 'Vizitoni faqen tonë të internetit për më shumë informacion rreth shtojcave dhe shtesave tona.','Order pay page' => 'Faqja e porosisë së pagesës','Order pay' => 'Urdhëroni pagesën','Enable order pay page optimizations' => 'Aktivizo optimizimin e faqes së pagesës së porosive','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Ndryshon paraqitjen e faqes së pagesës së porosisë për porositë ekzistuese në pritje të pagesës nga klienti.','Add widget areas to the order pay page' => 'Shtoni zonat e miniaplikacioneve në faqen e pagesës së porosisë','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Këto zona miniaplikacioni përdoren për të shtuar simbole besimi dhe distinktivë besimi në faqen e pagesës së porosisë.','Thank you page & order details layout' => 'Falemnderit faqe dhe faqosja e detajeve të porosisë','Order details optimizations' => 'Optimizimi i detajeve të porosisë','Enable thank you page and order details optimizations' => 'Aktivizo optimizimet e faqes së falenderimeve dhe detajeve të porosisë','Changes the layout of order details on the thank you page and account pages.' => 'Ndryshon paraqitjen e detajeve të porosisë në faqen e falenderimeve dhe faqet e llogarisë.','Enable order details customizations on email notifications' => 'Aktivizo personalizimet e detajeve të porosisë në njoftimet me email','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Shfaqni seksione të reja dhe ndryshoni rendin e seksioneve në njoftimet me email. Stilet e detajeve të porosive në njoftimet me email mbeten të pandryshuara.','Thank you page' => 'faqe faleminderit','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Këto opsione ndikojnë në faqen e falënderimeve, e njohur edhe si faqet e pranuara të porosive ose faqet e konfirmimit të porosisë.','Order details layout' => 'Paraqitja e detajeve të porosisë','Display the order details with wide layout on the thank you page' => 'Shfaqni detajet e porosisë me një plan urbanistik të gjerë në faqen e falënderimeve','Add widget areas to the thank you page' => 'Shtoni zonat e miniaplikacioneve në faqen e falënderimeve','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Këto zona miniaplikacioni përdoren për të shtuar simbole besimi dhe distinktivë besimi në faqen e falënderimeve.','Order actions' => 'Rendit veprimet','Choose in which position to display the order actions.' => 'Zgjidhni në cilin pozicion do të shfaqen veprimet e rendit.','Inside the order overview' => 'Brenda përmbledhjes së porosisë','After the order overview' => 'Pas pasqyrës së porosisë','After order sections' => 'Seksionet pas porosisë','Order status' => 'Statusi i porosisë','Display the order status progress bar' => 'Shfaq shiritin e progresit të statusit të porosisë','Choose in which position to display the section.' => 'Zgjidhni në cilin pozicion do të shfaqet seksioni.','After the order overview and payment instructions' => 'Pas përmbledhjes së porosisë dhe udhëzimeve të pagesës','Before the order items section' => 'Përpara seksionit të artikujve të porosisë','Inside the order items section' => 'Brenda seksionit të artikujve të porosisë','After the order items section' => 'Pas seksionit të artikujve të porosisë','On the sidebar' => 'Në shiritin anësor','Order downloads' => 'Porosit shkarkime','Gift message' => 'Mesazh dhuratë','Tools' => 'Mjetet','Troubleshooting' => 'Zgjidhja e problemeve','Debug options' => 'Opsionet e korrigjimit','Debug mode' => 'Modaliteti i korrigjimit','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Përdorimi i modalitetit të korrigjimit ndikon në performancën e faqes në internet. Përdoreni këtë opsion vetëm gjatë zgjidhjes së problemeve.','Load unminified assets' => 'Ngarko aktivet e paminifikuara','Enhanced select fields' => 'Fushat e zgjedhura të përmirësuara','Fix automatic zoom-in on form fields' => 'Rregulloni zmadhimin automatik në fushat e formularit','Set <code>font-size</code> inside form fields to 16px' => 'Cakto <code>font-size</code> brenda fushave të formës në 16 px','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Cilësimet','Support' => 'Mbështetje','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Përmirësojeni në PRO</a> për të zhbllokuar më shumë opsione.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentale)','Please verify your phone number.' => 'Ju lutemi verifikoni numrin tuaj të telefonit.','The Bluehost Plugin' => 'Shtojca Bluehost','Custom fields' => 'Fushat e personalizuara','Enable custom shipping email field' => 'Aktivizo fushën e postës elektronike të personalizuar të transportit','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kur aktivizohet, fusha e postës elektronike të transportit nga shtojca Bluehost do të shtohet në formularin e arkëtimit.','Captcha Pro by BestWebSoft' => 'Captcha Pro nga BestWebSoft','Captcha position' => 'Pozicioni Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Përcaktoni pozicionin për të shfaqur seksionin captcha. Disa pozicione mund të mos funksionojnë në varësi të llojit të captcha-s të zgjedhur.','Selecting a pickup point is required before proceeding.' => 'Përpara se të vazhdoni, kërkohet përzgjedhja e një pike marrjeje.','Pickup point' => 'Pika e marrjes','Pickup point not selected yet.' => 'Pika e marrjes nuk është zgjedhur ende.','Pickup point:' => 'Pika e marrjes:','Mailchimp for WooCommerce' => 'Mailchimp për WooCommerce','Subscribe checkbox' => 'Kutia e zgjedhjes Abonohu','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Anuloni pozicionin për kutinë e kontrollit të abonimit në faqen e blerjes dhe shfaqeni gjithmonë në hapin e kontaktit','Before Shipping Address' => 'Adresa para dërgesës','(originally "%s")' => '(fillimisht &quot;%s&quot;)','After Shipping Address' => 'Adresa pas dërgimit','Selecting a collection point is required when shipping with FermoPoint.' => 'Përzgjedhja e një pike grumbullimi kërkohet kur transportohet me FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Nëse zgjidhet, informon përdoruesit për gabime shkrimi në email. (Kjo veçori është çaktivizuar sepse Fluid Checkout ofron funksionin. Ndryshimet në këtë opsion nuk do të hyjnë në fuqi)','Enable Mail Check: (disabled feature)' => 'Aktivizo kontrollin e postës: (funksioni i çaktivizuar)','Carrier:' => 'Transportuesi:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Marketingu me email i WooCommerce','Sign up checkbox position' => 'Regjistrohu për pozicionin e kutisë së kontrollit','Move the sign up checkbox to the contact step' => 'Zhvendosni kutinë e kontrollit të regjistrimit në hapin e kontaktit','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kur aktivizohet, kutia e kontrollit do të zhvendoset në hapin e kontaktit, pavarësisht nga vendndodhja e ekranit të përcaktuar në cilësimet e shtojcës Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Përparimi i blerjes','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Nxjerr seksionin e hapave të blerjes nga Betheme në faqet e arkës, karrocave dhe porosive të marra.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Thërrime buke','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Nxjerr seksionin e bukës nga tema Fennik kur përdor kokën dhe fundin e Fluid Checkout.','Theme Go' => 'Tema Shko','My account layout' => 'Paraqitja e llogarisë sime','Enable wide layout on "My account" page.' => 'Aktivizo paraqitjen e gjerë në faqen &quot;Llogaria ime&quot;.','Theme Impreza' => 'Tema Impreza','Header' => 'Kreu','Spacing for site header at the checkout page (in pixels)' => 'Hapësira për kokën e sajtit në faqen e blerjes (në piksel)','Only applicable when using the Impreza theme header at the checkout page.' => 'Zbatohet vetëm kur përdorni kokën e temës Impreza në faqen e arkës.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Nxirrni seksionin e hapave të blerjes nga tema Kapee në faqet e arkës, karrocës dhe porosisë së marrë.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Nxirrni seksionin e hapave të blerjes nga tema Porto në faqet e arkës, karrocave dhe porosive të marra.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Nxirrni seksionin e hapave të arkëtimit nga tema Pressmart në faqet e arkës, karrocave dhe porosive të marra.','Theme The Gem' => 'Tema Perlë','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Nxirrni seksionin e hapave të blerjes nga tema Gem kur përdorni kokën dhe fundin e fundit të Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Nxirrni seksionin e hapave të arkëtimit nga tema Woodmart kur përdorni kokën dhe fundin e fundit të Fluid Checkout.','Checkout options' => 'Opsionet e blerjes','Disable the theme checkout options' => 'Çaktivizo opsionet e blerjes së temës','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Opsionet që shfaqin imazhin e produktit, fushën e sasisë, butonin e heqjes dhe lidhjen me faqen e produktit të shtuar nga tema janë çaktivizuar si parazgjedhje.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Përparimi i porosisë','Display order progress from the theme' => 'Shfaq progresin e porosisë nga tema','Display the form field labels visible on the page' => 'Shfaqni etiketat e fushave të formave të dukshme në faqe','It is recommended to keep this option enabled for a better user experience.' => 'Rekomandohet ta mbani këtë opsion të aktivizuar për një përvojë më të mirë të përdoruesit.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Shtoni fusha shtesë në formularin e arkës','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Shton një email shtesë transporti dhe një fushë telefoni transporti në seksionin e adresës së transportit.','Go to the home page' => 'Shkoni në faqen kryesore','Skip to content' => 'Kalo te përmbajtja','Create an account' => 'Krijo një llogari','Log in to your account' => 'Hyni në llogarinë tuaj','Already have an account?' => 'Keni tashmë një llogari?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'I identifikuar si %1$s. <a href="%2$s">Dilni</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Porosia juaj ka një shumë totale të detyrimit prej %s. Nuk ka nevojë për pagesë të mëtejshme.','Close and continue with checkout' => 'Mbylle dhe vazhdo me arkën','Continue' => 'Vazhdoni','Parcel terminal' => 'Terminali i parcelave','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ky miniaplikacion është zëvendësuar nga Fluid Checkout.</p><p> Kur përdorni Fluid Checkout, faqja e arkës duhet të përdorë kodin e shkurtër origjinal të WooCommerce <code>[woocommerce_checkout]</code> për të funksionuar siç duhet.</p><p> Për më shumë informacion, vizitoni dokumentacionin e Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Seksione shtesë të kokës','Output additional header sections if enabled in the theme settings.' => 'Nxirrni seksione shtesë të kokës nëse aktivizohen në cilësimet e temës.','More information' => 'Më shumë informacion','Pick a Locker' => 'Zgjidh një dollap me kyç','Page template' => 'Shablloni i faqes','Use `Order confirmation` page template for block-based themes' => 'Përdorni shabllonin e faqes `Konfirmimi i porosisë` për temat e bazuara në bllok','Only applies when using a block-based theme.' => 'Vlen vetëm kur përdoret një temë e bazuar në blloke.','WooCommerce Stripe Gateway' => 'Porta e Gjurmëve të WooCommerce','Payment form' => 'Formulari i pagesës','Apply styles to the Stripe payment form fields' => 'Aplikoni stile në fushat e formularit të pagesës Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kur aktivizohet, Fluid Checkout do të aplikojë stile të optimizuara për pajtueshmëri me plugin-in. Mund të dëshironi ta çaktivizoni këtë nëse po përdorni stile të personalizuara për fushat e formularit të pagesës Stripe.','Theme Nyture' => 'Theme Nature','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Nxirr seksionin e hapave të arkëtimit nga tema Nyture kur përdor Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'U lejon klientëve të kryejnë pagesa për porositë që ose krijohen manualisht nga administratori i dyqanit ose nuk përfundohen gjatë arkëtimit.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Shtojca WooCommerce Checkout Manager nga Quadlayers nuk është e pajtueshme me Fluid Checkout.','Company name field for billing address' => 'Fusha e emrit të kompanisë për adresën e faturimit','Change visibility for the company name field for the billing address section on the checkout form.' => 'Ndryshoni dukshmërinë për fushën e emrit të kompanisë për seksionin e adresës së faturimit në formularin e arkëtimit.','Theme Bookshelf' => 'Raft librash me temë','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Nxirr seksionin e hapave të arkëtimit nga tema Bookshelf kur përdor Fluid Checkout.','Account password' => 'Fjalëkalimi i llogarisë','An account will be created with the information provided at checkout when completing the order.' => 'Një llogari do të krijohet me informacionin e dhënë në arkë gjatë përfundimit të porosisë.','Choose the style of the progress bar.' => 'Zgjidhni stilin e shiritit të progresit.','Bars' => 'Bare','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Paraqitja e faqes WooCommerce','Force wide layout on WooCommerce pages' => 'Detyro paraqitjen e gjerë në faqet WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Kjo siguron që seksioni i përmbajtjes të mos jetë shumë i ngushtë në faqet e WooCommerce, duke përfshirë faqet e arkëtimit, shportës, porosisë së marrë, pagesës së porosisë dhe llogarisë.','WooCommerce Smart Coupons' => 'Kupona të Mençura WooCommerce','Position on checkout page' => 'Pozicioni në faqen e arkëtimit','Choose where to display the available coupons section on the checkout page.' => 'Zgjidhni se ku të shfaqet seksioni i kuponave të disponueshëm në faqen e pagesës.','Before the progress bar' => 'Para shiritit të progresit','After the progress bar' => 'Pas shiritit të progresit','Before coupon codes section' => 'Para seksionit të kodeve të kuponave','Format phone numbers according to the rules for each country.' => 'Formatoni numrat e telefonit sipas rregullave për secilin vend.','Use precise phone number validation' => 'Përdorni validimin e saktë të numrit të telefonit','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Kjo është një veçori eksperimentale dhe mund të mos funksionojë siç pritet në të gjitha konfigurimet. Përdoreni me kujdes.','Phone number validation types used when precise validation is enabled.' => 'Llojet e validimit të numrit të telefonit të përdorura kur aktivizohet validimi i saktë.','Mobile' => 'Celular','Fixed line' => 'Linjë fikse','Toll free' => 'Pa pagesë','Or' => 'Ose','Contact' => 'Kontakti','Multi step' => 'Shumë hapa','2 columns' => '2 kolona','1 column' => '1 kolonë','Before checkout steps' => 'Hapat para arkëtimit','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Kur përdorni paraqitjen e arkëtimit <em>&quot;1 kolonë&quot;,</em> ky opsion është gjithmonë i vendosur në <em>&quot;Para hapave të arkëtimit&quot;</em> dhe vlen edhe për pamjen e desktopit.','Position for the extra order summary section on mobile.' => 'Pozicioni për seksionin shtesë të përmbledhjes së porosisë në celular.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Opsioni <em>&quot;Në kokën e faqes&quot;</em> zbatohet vetëm kur përdoret koka pa shpërqendrime.','On the site header (requires distraction-free header)' => 'Në kokën e faqes (kërkon kokë pa shpërqendrime)','Initial state for the expansible order summary section on mobile.' => 'Gjendja fillestare për seksionin e përmbledhjes së porosisë së zgjerueshme në celular.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Ne rekomandojmë ta vendosni si <em>të zgjeruar</em> për vendet e mëposhtme për shkak të kërkesave rregullatore: <strong>Gjermania</strong> , <strong>Austria</strong> , <strong>Zvicra</strong> , <strong>Holanda</strong> , <strong>Polonia</strong> , <strong>Belgjika</strong> dhe <strong>Franca</strong> .','Collapsed' => 'Palosur','Expanded' => 'Zgjeruar','Do not show' => 'Mos e shfaq','yes' => 'po','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Fusha e numrit të telefonit të dërgesës mund të detyrohet të shënohet si &quot;e detyrueshme&quot; nëse seksioni i adresës së faturimit shfaqet pas seksionit të adresës së dërgesës dhe fusha e numrit të telefonit të faturimit është vendosur si &quot;e detyrueshme&quot;. Kjo është e nevojshme për të siguruar që adresa e dërgesës të mund të kopjohet në adresën e faturimit kur ky opsion është i zgjedhur, përndryshe klienti mund të mos jetë në gjendje të plotësojë formularin e pagesës.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Fusha e numrit të telefonit të faturimit mund të detyrohet të shënohet si &quot;e detyrueshme&quot; nëse seksioni i adresës së faturimit shfaqet përpara seksionit të adresës së dërgesës dhe fusha e numrit të telefonit të dërgesës është vendosur si &quot;e detyrueshme&quot;. Kjo është e nevojshme për të siguruar që adresa e dërgesës të mund të kopjohet në adresën e faturimit kur ky opsion është i zgjedhur, përndryshe klienti mund të mos jetë në gjendje të plotësojë formularin e pagesës.','Settings profiles' => 'Profilet e cilësimeve','Settings profile' => 'Profili i cilësimeve','You do not have permission to perform this action.' => 'Nuk keni leje për të kryer këtë veprim.','You do not have permission to activate plugins.' => 'Nuk keni leje për të aktivizuar plugin-e.','Missing plugin.' => 'Mungon plugin.','Plugin activated.' => 'Plugini u aktivizua.','The following changes will be applied:' => 'Do të zbatohen ndryshimet e mëposhtme:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Që nga Fluid Checkout 5.0, cilësimet ruhen ndryshe. Opsionet e trashëguara ruhen ende në bazën e të dhënave për të lejuar uljet në versionet e mëparshme nëse është e nevojshme.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Dyqani juaj ka qenë duke funksionuar për rreth 2 javë me cilësimet e reja, kështu që ju mund të pastroni opsionet e trashëguara të ruajtura në bazën e të dhënave. Ju lutemi vini re se pas pastrimit, nëse duhet të kaloni në versionet e mëparshme të plugin-it, ai do të përdorë vlerat fillestare për të gjitha cilësimet.','Fluid Checkout settings cleanup' => 'Pastrimi i cilësimeve të Fluid Checkout','Delete leftover options' => 'Fshi opsionet e mbetura','Help us improve Fluid Checkout' => 'Na ndihmoni të përmirësojmë Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Ndani raportet anonime të mjedisit të faqes me Fluid Checkout për të marrë mbështetje më të shpejtë dhe për të na ndihmuar të përmirësojmë përputhshmërinë dhe të matim ndikimin. Nuk përfshihen të dhëna të klientëve, përdoruesve ose të dhëna të ndjeshme. Mund të zgjidhni se çfarë ndahet në çdo kohë nga cilësimet e Mjeteve.','Enable site environment reports' => 'Aktivizo raportet e mjedisit të faqes','Review settings' => 'Rishiko cilësimet','This preview has expired. Reload the admin page to start a new preview.' => 'Ky parapamje ka skaduar. Ringarko faqen e administratorit për të filluar një parapamje të re.','Preview expired' => 'Pamja paraprake skadoi','Orders cannot be placed in the preview.' => 'Porositë nuk mund të bëhen në pamjen paraprake.','Logging in is not available in the preview.' => 'Hyrja nuk është e disponueshme në pamjen paraprake.','Accounts cannot be created in the preview.' => 'Llogaritë nuk mund të krijohen në pamjen paraprake.','Requests to other sites are blocked in the preview.' => 'Kërkesat për faqet e tjera bllokohen në pamjen paraprake.','Processing…' => 'Duke u përpunuar…','Something went wrong. Please try again.' => 'Diçka shkoi keq. Ju lutemi provoni përsëri.','Activate plugin' => 'Aktivizo plugin-in','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Paketa e plotë e arkëtimit','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Të gjitha veçoritë PRO + të gjitha shtesat, një çmim. Shabllone dizajni, faqe të optimizuara për shportën dhe porositë e pranuara, përputhje llogarish dhe shumë më tepër.','Optimized order pay page' => 'Faqe e optimizuar për pagesën e porosisë','Express checkout buttons from supported payment methods' => 'Butona për arkëtim të shpejtë nga metodat e mbështetura të pagesës','Delayed account creation' => 'Krijimi i vonuar i llogarisë','Address autocomplete with Google Maps APIs' => 'Plotësimi automatik i adresës me API-të e Hartave të Google','Multiple saved addresses with the address book' => 'Adresa të shumta të ruajtura me librin e adresave','EU-VAT assistant' => 'Asistent i TVSH-së në BE','Hide this section' => 'Fshih këtë seksion','Learn more' => 'Mëso më shumë','Get early access' => 'Merrni qasje të hershme','Activate add-on' => 'Aktivizo shtesën','Get more out of your checkout journey' => 'Përfitoni më shumë nga udhëtimi juaj i pagesës','Test API key' => 'Çelësi i API-t të testimit','Guided setup' => 'Konfigurim i udhëhequr','Options' => 'Opsionet','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Konfiguroni paraqitjen dhe dizajnin në <a href="%s">opsionet e arkëtimit</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Aktivizoni pagesën si mysafir dhe/ose rishikoni <a href="%s">cilësimet e llogarive të klientëve</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Aktivizo faqet e optimizuara të <a href="%1$s">shportës</a> , <a href="%2$s">falënderimeve</a> dhe <a href="%3$s">pagesës së porosive</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Aktivizo <a href="%s">plotësimin automatik të adresës</a> nga Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Aktivizo adresa të shumta të ruajtura me <a href="%s">librin e adresave</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Kontrolloni nëse ka ndonjë <a href="%s">opsion integrimi</a> të disponueshëm për temën ose shtojcat e tjera që keni instaluar.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Merrni mbështetje më të shpejtë dhe na ndihmoni të përmirësojmë përputhshmërinë dhe të matim ndikimin. <a href="%s">Aktivizoni gjurmimin e përdorimit</a> nga cilësimet e mjeteve.','Missing settings tab.' => 'Mungon skeda e cilësimeve.','Getting started' => 'Fillimi','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Shkëlqyeshëm! Faqja juaj e pagesës tani po funksionon në Fluid Checkout.</strong> Ja disa hapa për të filluar:','Completed' => 'Përfunduar','Preview report data' => 'Parapamje paraprake e të dhënave të raportit','Send now' => 'Dërgo tani','Auto-detect' => 'Zbulo automatikisht','Afrikaans' => 'Afrikanisht','Albanian' => 'shqip','Amharic' => 'Amarike','Arabic' => 'Arabisht','Armenian' => 'armenisht','Azerbaijani' => 'Azerbajxhanisht','Basque' => 'bask','Belarusian' => 'Bjellorusisht','Bengali' => 'Bengalisht','Bosnian' => 'boshnjak','Bulgarian' => 'bullgar','Burmese' => 'birmanisht','Catalan' => 'Katalanisht','Chinese' => 'kinez','Chinese (Simplified)' => 'Kinezisht (e thjeshtuar)','Chinese (Hong Kong)' => 'Kinezisht (Hong Kong)','Chinese (Traditional)' => 'Kinezisht (Tradicionale)','Croatian' => 'Kroatisht','Czech' => 'Çeke','Danish' => 'danez','Dutch' => 'holandez','English' => 'Anglisht','English (Australian)' => 'Anglisht (Australian)','English (Great Britain)' => 'Anglisht (Britania e Madhe)','Estonian' => 'Estonisht','Farsi' => 'Farsi','Finnish' => 'finlandez','Filipino' => 'Filipinase','French' => 'frëngjisht','French (Canadian)' => 'Frëngjisht (Kanadezisht)','Galician' => 'galike','Georgian' => 'gjeorgjian','German' => 'gjermanisht','Greek' => 'grek','Gujarati' => 'Guxharatisht','Hebrew' => 'Hebraisht','Hindi' => 'Hindisht','Hungarian' => 'hungareze','Icelandic' => 'Islandeze','Indonesian' => 'Indonezisht','Italian' => 'italiane','Japanese' => 'Japonez','Kannada' => 'Kannada','Kazakh' => 'Kazake','Khmer' => 'Khmer','Korean' => 'Koreane','Kyrgyz' => 'kirgizisht','Lao' => 'Lao','Latvian' => 'letonisht','Lithuanian' => 'lituanisht','Macedonian' => 'maqedonase','Malay' => 'Malajisht','Malayalam' => 'Malajalamisht','Marathi' => 'Marathi','Mongolian' => 'mongolisht','Nepali' => 'Nepalisht','Norwegian' => 'Norvegjisht','Polish' => 'polak','Portuguese' => 'portugalisht','Portuguese (Brazil)' => 'Portugalisht (Brazil)','Portuguese (Portugal)' => 'Portugalisht (Portugali)','Punjabi' => 'Punjabi','Romanian' => 'rumanisht','Russian' => 'ruse','Serbian' => 'serbisht','Sinhalese' => 'Sinhaleze','Slovak' => 'Sllovakisht','Slovenian' => 'sllovenisht','Spanish' => 'Spanjisht','Spanish (Latin America)' => 'Spanjisht (Amerika Latine)','Swahili' => 'Suahili','Swedish' => 'suedeze','Tamil' => 'Tamil','Telugu' => 'Teluguisht','Thai' => 'Tajlandeze','Turkish' => 'turk','Ukrainian' => 'ukrainas','Urdu' => 'Urdu','Vietnamese' => 'Vietnamez','Zulu' => 'Zulu','Google address autocomplete' => 'Autoplotësimi i adresës në Google','Google Places API version' => 'Versioni i API-t të Vendeve të Google-it','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Zgjidhni versionin e API-t të Vendeve të Google-it që dëshironi të përdorni. Ne ju rekomandojmë të kaloni në API-n e ri të Vendeve sa më shpejt të jetë e mundur.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Ne rekomandojmë përdorimin e &quot;Places API (E Re)&quot;. Duke filluar nga 1 Marsi 2025, Google do ta zhvendosë versionin &quot;Places API (Legacy)&quot; në statusin Legacy, që do të thotë se nuk do të jeni më në gjendje ta aktivizoni këtë shërbim për çelësat e rinj të API-t dhe se ai version i API-t përfundimisht nuk do të jetë më i disponueshëm. Llogaritë ekzistuese që tashmë përdorin Legacy API mund të vazhdojnë të funksionojnë pa ndërprerje.','(Recommended)' => '(Rekomandohet)','Google API key' => 'Çelësi i API-t të Google-it','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Ngjit çelësin tënd të API-t të Google dhe përdor butonin e testimit për të konfirmuar se funksionon për këtë faqe interneti. Sigurohu që çelësi është i vlefshëm dhe i lejuar për domenin tënd, përndryshe fusha e adresës mund të bllokohet duke i penguar klientët të përfundojnë porositë e tyre.','Enable Google address autocomplete' => 'Aktivizo plotësimin automatik të adresës në Google','Enable address autocompletion using the Google Maps APIs.' => 'Aktivizo plotësimin automatik të adresës duke përdorur API-të e Hartave Google.','Google API language' => 'Gjuha e API-t të Google-it','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Kjo gjuhë do të përdoret për të shfaqur sugjerimet e adresave të API-t të Vendeve të Google dhe adresat gjithashtu do të plotësohen automatikisht në këtë gjuhë.','Result types' => 'Llojet e rezultateve','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Lëreni bosh për të pranuar çdo lloj rezultati, i cili zakonisht jep rezultate më të mira përputhjeje. <a href="%s" target="_blank">Shihni dokumentacionin për më shumë detaje</a> .<br> Zgjidhni deri në 5 lloje rezultatesh kërkimi për adresa për t&#39;i kthyer në fushat e plotësimit automatik të adresave.<br> Vizitoni dokumentacionin e Google Maps për të mësuar më shumë rreth <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">llojeve të mbështetura</a> .','Result types (Legacy API)' => 'Llojet e rezultateve (API i trashëguar)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Çfarë lloj rezultatesh kërkimi adresash duhet të kthehen kur përdoret API-ja e Vendeve (Legacy).<br> Vizitoni dokumentacionin e API-t të Vendeve të Google-it të Trashëguara për të mësuar më shumë rreth <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">llojeve të mbështetura</a> .','Company fields' => 'Fushat e kompanisë','Enable autocomplete for the company name if available' => 'Aktivizo plotësimin automatik për emrin e kompanisë nëse është i disponueshëm','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Aktivizo plotësimin automatik të fushës së kompanisë me informacionin e emrit të kompanisë kur kthehet nga API-të e Hartave të Google.','Business search' => 'Kërkim biznesi','Enable search for businesses in the company field' => 'Aktivizo kërkimin për biznese në fushën e kompanisë','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Aktivizoni sugjerimin e adresave të shoqëruara me një biznes kur shkruani në fushën e kompanisë, pastaj plotësoni automatikisht të gjitha fushat e adresave kur zgjidhet një biznes nga sugjerimet.','Company result types' => 'Llojet e rezultateve të kompanisë','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Zgjidhni deri në 5 lloje rezultatesh kërkimi adresash për t&#39;i kthyer në fushat e plotësimit automatik të kompanisë.<br> Vlera e rekomanduar është <code>establishment</code> , i cili përfshin shumicën e llojeve të bizneseve.<br> Lëreni bosh për të pranuar çdo lloj rezultati, duke përfshirë rezultatet që nuk lidhen me bizneset.<br> Vizitoni dokumentacionin e Google Maps për të mësuar më shumë rreth <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">llojeve të mbështetura</a> .','Google logo' => 'Logoja e Google','Show text and logo "Powered by Google"' => 'Shfaq tekstin dhe logon &quot;Mundësuar nga Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kur është zgjedhur, teksti dhe logoja &quot;Me mbështetjen e Google&quot; do të shfaqen në fund të kutisë së sugjerimeve të plotësimit automatik të adresës.','Brasil API address autocomplete' => 'Autoplotësimi i adresës së API-t të Brasil-it','Brasil API' => 'API-ja e Brazilit','Enable Brasil API address autocomplete for CEP fields' => 'Aktivizo plotësimin automatik të adresës Brasil API për fushat CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Përdorni Brasil API për të marrë dhe plotësuar automatikisht adresat duke përdorur fushën CEP/Postcode. I përshtatshëm vetëm për adresat braziliane.','API version' => 'Versioni i API-t','Choose which version of the Brasil API CEP method to use.' => 'Zgjidhni versionin e metodës Brasil API CEP që do të përdorni.','Address book migration' => 'Migrimi i librit të adresave','WooCommerce addresses' => 'Adresat e WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopjoni adresat ekzistuese të dërgesës dhe faturimit nga WooCommerce në librin e adresave të klientëve.','Enable the address book feature' => 'Aktivizo funksionin e librit të adresave','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Lejoni klientët të ruajnë adresa të shumta dhe të përcaktojnë adresën e parazgjedhur që do të përdoret për dërgesa dhe faturim.','Address labels' => 'Etiketat e adresave','Allow customers to add a custom label for each address' => 'Lejoni klientët të shtojnë një etiketë të personalizuar për secilën adresë','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Etiketat e adresave ua bëjnë më të lehtë klientëve të dallojnë adresat e tyre të ruajtura (p.sh.: &quot;Shtëpia e Mamit&quot;). Etiketat e adresave janë private për klientët dhe nuk do të shfaqen ose shtypen në faqen e detajeve të porosisë ose në fatura.','Display layout' => 'Paraqitja e ekranit','Choose how saved addresses are displayed at checkout and on the cart.' => 'Zgjidhni se si shfaqen adresat e ruajtura në arkë dhe në shportë.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Vlen në arkë dhe në shportë. Adresat e ruajtura në faqen e llogarisë përdorin gjithmonë paraqitjen e kartave.','Address cards' => 'Kartat e adresës','Address list' => 'Lista e adresave','Dropdown field' => 'Fusha e menysë zbritëse','Address search' => 'Kërkimi i adresës','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Shfaq filtrin e kërkimit të adresave në frontend kur klienti ka të paktën këtë numër adresash të ruajtura në dispozicion.','Not used when display layout is set to dropdown field.' => 'Nuk përdoret kur paraqitja e ekranit është vendosur në fushën me zbritje.','Addresses' => 'Adresat','Enable cart page optimizations to see more options' => 'Aktivizoni optimizimet e faqes së shportës për të parë më shumë opsione','Sticky order summary' => 'Përmbledhje e porosisë së pandryshueshme','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Zgjidhni pozicionin ku do të shfaqet seksioni i kodeve të kuponave në faqen e shportës. Vlen vetëm kur shporta AJAX është e aktivizuar dhe nëse përdorimi i kodeve të kuponave është i aktivizuar në cilësimet e WooCommerce.','Layout of cross-sell' => 'Paraqitja e shitjes së kryqëzuar','Cross-sells displayed' => 'Shitjet e kryqëzuara të shfaqura','Items' => 'Artikuj','Cart page optimization' => 'Optimizimi i faqes së shportës','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Jepini shportës suaj të njëjtën paraqitje të qartë dhe të fokusuar në konvertim si në arkë.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Përputhni paraqitjen e shportës me faqen e pagesës për një udhëtim blerjeje të qëndrueshëm.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Mbajeni shportën gjithmonë të përditësuar në sfond, pa ringarkime të plota të faqes kur ndryshojnë sasitë.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Vendosni kodet e kuponave, dërgesat dhe shitjet e kryqëzuara pikërisht aty ku ato konvertojnë më mirë.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Mbajeni përmbledhjen e porosisë të dukshme gjatë lëvizjes dhe shtoni simbole besimi aty ku blerësit kanë nevojë për siguri.','Columns' => 'Kolona','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Stile të përgjithshme për hapat e arkëtimit, përmbledhjen e porosisë dhe seksionet e tjera. Vlen për faqet e tjera të arkëtimit, shportës, falënderimeve (porosia e marrë) dhe shikimit të porosisë.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Kur përdorni paraqitjen <em>&quot;1 kolonë&quot;</em> me shabllonin e dizajnit <em>&quot;Ndaj&quot;</em> , një kolonë e djathtë shfaqet vetëm nëse zona e vegëlve të shiritit anësor të faqes është aktive (Shiriti anësor i Arkës, Shiriti anësor i Shportës ose Shiriti anësor i Porosisë së Marrë). Përndryshe, faqja mbetet si një kolonë e vetme me stile të Ndarjes.','Split column background' => 'Sfondi i kolonës së ndarë','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Zgjidh një ngjyrë sfondi për kolonën dytësore të Dizajnit të Ndarjes. Lëre bosh për të përdorur ngjyrën e sfondit të përmbledhjes së renditjes.','Page templates' => 'Shabllonet e faqeve','Checkout template' => 'Shablloni i arkëtimit','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Rekomandohet për më pak shpërqendrime gjatë arkëtimit. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Lexoni hulumtimin rreth braktisjes së shportës</a> .','Sticky progress bar' => 'Shiriti ngjitës i progresit','Progress bar style' => 'Stili i shiritit të progresit','Order totals' => 'Totali i porosive','Background color' => 'Ngjyra e sfondit','Action link' => 'Lidhja e veprimit','Mobile order summary' => 'Përmbledhje e porosisë në celular','Mobile initial state' => 'Gjendja fillestare e celularit','Enable editing cart items at checkout' => 'Aktivizo modifikimin e artikujve të shportës në arkë','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Lejoni klientët të ndryshojnë sasitë e produkteve ose të heqin artikujt direkt në faqen e pagesës.','Cart item errors' => 'Gabimet e artikujve të shportës','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Vlen vetëm kur kodi i kuponit shfaqet si një seksion i veçantë në faqet e arkëtimit ose të shportës, dhe nëse përdorimi i kodeve të kuponit është aktivizuar në cilësimet e WooCommerce.','Coupon codes position' => 'Pozicioni i kodeve të kuponave','Apply coupon button' => 'Zbato butonin e kuponit','Select style of the "apply coupon" button.' => 'Zgjidhni stilin e butonit &quot;zbato kuponin&quot;.','Address line 2' => 'Rreshti i adresës 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ky cilësim ndahet midis seksioneve të Arkëtimit dhe Marrjes Lokale. Në seksionin e Marrjes Lokale, vendos gjithashtu nëse përzgjedhësi i Dërgesës/Marrjes shfaqet brenda seksionit të metodës së dërgesës (para adresës) apo si një seksion i veçantë (pas).','Customer accounts' => 'Llogaritë e klientëve','Guest checkout' => 'Arkëtim për mysafirë','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Opsionet e pagesës, hyrjes dhe krijimit të llogarisë si mysafir nga faqja e cilësimeve të Llogarive WooCommerce. Ato menaxhohen këtu për lehtësinë tuaj, kështu që mund të përdorni vlera të ndryshme për profilin e cilësimeve.','Allow customers to checkout without an account' => 'Lejoni klientët të kryejnë pagesën pa një llogari','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Rekomandohet</strong> në mënyrë që klientëve të mos u kërkohet të krijojnë një llogari ose të identifikohen gjatë përfundimit të blerjes, gjë që mund të ulë normat e konvertimit.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kur është çaktivizuar, klientët duhet të identifikohen ose të krijojnë një llogari për të përfunduar blerjen.','Login at checkout' => 'Kyçu në arkë','Enable log-in during checkout' => 'Aktivizo hyrjen gjatë përfundimit të pagesës','Show a link for returning customers to log in from the checkout page.' => 'Shfaq një lidhje për klientët që kthehen për t&#39;u identifikuar nga faqja e pagesës.','Account creation' => 'Krijimi i llogarisë','Allow customers to create an account during checkout' => 'Lejoni klientët të krijojnë një llogari gjatë pagesës','Customers can create an account before placing their order.' => 'Klientët mund të krijojnë një llogari përpara se të bëjnë porosinë e tyre.','Allow customers to create an account from the My account page' => 'Lejoni klientët të krijojnë një llogari nga faqja Llogaria ime','Customers can register a new account from the My account page.' => 'Klientët mund të regjistrojnë një llogari të re nga faqja Llogaria ime.','Username' => 'Emri i përdoruesit','Generate from customer\'s name' => 'Gjeneroni nga emri i klientit','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Rekomandohet</strong> në mënyrë që klientëve të mos u kërkohet të zgjedhin një emër përdoruesi gjatë pagesës, gjë që mund të ulë normat e konvertimit.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Një emër përdoruesi gjenerohet nga emri i klientit ose nga adresa e email-it kur një emër nuk mund të përdoret.','Password' => 'Fjalëkalimi','Send password setup link' => 'Dërgo lidhjen e konfigurimit të fjalëkalimit','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Rekomandohet</strong> në mënyrë që klientëve të mos u kërkohet të caktojnë një fjalëkalim gjatë pagesës, gjë që mund të ulë normat e konvertimit.','Customers receive an email to create their password securely.' => 'Klientët marrin një email për të krijuar fjalëkalimin e tyre në mënyrë të sigurt.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Lejoni klientët e regjistruar të përfundojnë pagesën pa u identifikuar dhe ta shoqërojnë porosinë me llogarinë e tyre ekzistuese kur të dhënat e kontaktit përputhen.','Existing account message' => 'Mesazh i llogarisë ekzistuese','Let customers create an account after placing their order, from the thank you page.' => 'Lejojini klientët të krijojnë një llogari pasi të bëjnë porosinë e tyre, nga faqja e falënderimit.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Opsionet në këtë seksion janë të disponueshme kur aktivizohen pagesa si mysafir dhe përputhja e llogarisë. Aktivizoni të dyja veçoritë e mësipërme për të konfiguruar krijimin e vonuar të llogarisë.','Enable delayed account creation' => 'Aktivizo krijimin e vonuar të llogarisë','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Aktivizo vonesën e krijimit të llogarisë kur janë aktivizuar si pagesa për mysafirë ashtu edhe përputhja e llogarisë.','Section position' => 'Pozicioni i seksionit','Before customer details section' => 'Para seksionit të të dhënave të klientit','After customer details section' => 'Pas seksionit të të dhënave të klientit','Account creation benefits' => 'Përfitimet e krijimit të llogarisë','Leaving the field empty will display the default text.' => 'Nëse e lini fushën bosh, do të shfaqet teksti i parazgjedhur.','Inline buttons' => 'Butona të integruar','Required fields' => 'Fushat e detyrueshme','Enable gift message fields at checkout' => 'Aktivizo fushat e mesazheve të dhuratës në arkë','Expanded gift message' => 'Mesazh i zgjeruar i dhuratës','Display gift message field always expanded' => 'Fusha e mesazhit të dhuratës së shfaqur është gjithmonë e zgjeruar','Gift message in order details' => 'Mesazh dhurate në detajet e porosisë','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Nuk ka integrime të disponueshme për momentin në këtë seksion. Opsionet që lidhen me secilin plugin dhe temë do të shfaqen këtu vetëm kur ai plugin ose temë të jetë aktivizuar.','Phone fields' => 'Fushat e telefonit','Field visibility' => 'Dukshmëria në terren','Field position' => 'Pozicioni në fushë','Phone country code & validation' => 'Kodi i vendit të telefonit dhe validimi','Country' => 'Vendi','Enable country on phone fields' => 'Aktivizo vendin në fushat e telefonit','Filter countries for shipping or billing' => 'Filtro vendet për dërgesë ose faturim','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Kufizoni përzgjedhësin e vendit në secilën fushë telefoni në vendet e lejuara për dërgesë ose faturim në dyqanin tuaj.','Validation' => 'Validimi','Enable simple validation based on country rules' => 'Aktivizoni validimin e thjeshtë bazuar në rregullat e vendit','Checks that the phone number is valid for the selected country, including country code and length.' => 'Kontrollon që numri i telefonit është i vlefshëm për vendin e zgjedhur, duke përfshirë kodin e vendit dhe gjatësinë.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Kontroll më i rreptë që numri të jetë i vlefshëm për celular, linjë fikse ose ndonjë lloj tjetër i pranuar për vendin e zgjedhur. Mund të refuzojë disa numra të vlefshëm.','Validation types' => 'Llojet e validimit','Placeholders' => 'Mbajtës të vendeve','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Nuk ka çelësa licence për t&#39;u menaxhuar për momentin. Çelësat e licencës do të shfaqen këtu kur një plugin ose shtesë e licencuar e Fluid Checkout është aktive.','Default delivery type' => 'Lloji i parazgjedhur i dorëzimit','Choose which delivery type will be selected by default.' => 'Zgjidhni se cili lloj dorëzimi do të zgjidhet si parazgjedhje.','Shipping zone fields' => 'Fushat e zonës së transportit detar','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Zgjidhni cilat fusha do të shfaqen për fushat e filtrit të zonës lokale të transportit të marrjes. Lëreni bosh për të shfaqur të gjitha opsionet e disponueshme.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Këto fusha do të shfaqen si një filtër për metodat lokale të transportit me marrje. Disa fusha mund të shfaqen ende në arkë kur nuk zgjidhen këtu, nëse shtojcat e përputhshme kërkojnë që ato të funksionojnë siç duhet.','Order shipping address' => 'Adresa e dërgesës së porosisë','Order pay page optimization' => 'Optimizimi i faqes së pagesës së porosisë','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Jepuni porosive të papaguara të njëjtën paraqitje të qartë dhe të fokusuar në konvertim si në arkë.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizoni paraqitjen e faqes së pagesës së porosisë për porositë në pritje të pagesës.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Përputhni përvojën e pagesës së porosisë me atë të arkës suaj për një udhëtim blerjeje të qëndrueshëm.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Shtoni simbole besimi dhe distinktiva aty ku blerësit kanë nevojë për siguri përpara se të paguajnë.','Thank you page optimization' => 'Faleminderit optimizimit të faqes','Make the thank you page and order details clearer for customers after they buy.' => 'Bëjeni faqen e falënderimit dhe detajet e porosisë më të qarta për klientët pasi të blejnë.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizoni faqen e falënderimit dhe detajet e porosisë së llogarisë me një paraqitje më të qartë.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Shfaq progresin e statusit të porosisë, veprimet, shkarkimet dhe shënimet aty ku kanë kuptim.','Customize order details sections on email notifications.' => 'Personalizoni seksionet e detajeve të porosisë në njoftimet me email.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Shtoni simbole besimi dhe distinktiva aty ku blerësit kanë nevojë për siguri pas blerjes.','Email notifications' => 'Njoftime me email','Enable thank you page and order details optimizations to see more options' => 'Aktivizoni faqen e falënderimit dhe optimizimet e detajeve të porosisë për të parë më shumë opsione','Use wide layout on thank you page' => 'Përdorni një paraqitje të gjerë në faqen e falënderimeve','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Këto opsione ndikojnë në faqen e falënderimeve, shikoni detajet e porosisë në faqet e llogarisë dhe në njoftimet me email.','Save settings' => 'Ruaj cilësimet','Docs' => 'Dokumente','Cart' => 'Shportë','Thank you' => 'Faleminderit','Address autocomplete' => 'Autoplotësimi i adresës','Trust badges' => 'Distinktivët e besimit','You do not have permission to save these settings.' => 'Nuk keni leje për të ruajtur këto cilësime.','Invalid save request.' => 'Kërkesë për ruajtje e pavlefshme.','Your settings have been saved.' => 'Cilësimet tuaja janë ruajtur.','Saving...' => 'Duke u ruajtur...','Settings could not be saved. Please try again.' => 'Cilësimet nuk mund të ruheshin. Ju lutemi provoni përsëri.','Dismiss notice' => 'Njoftim për shpërfillje','Open settings menu' => 'Hap menynë e cilësimeve','Close settings menu' => 'Mbyll menynë e cilësimeve','Preview' => 'Pamje paraprake','Expand preview' => 'Zgjero pamjen paraprake','Collapse preview' => 'Palos pamjen paraprake','Show header and footer' => 'Shfaq kokën dhe fundin e faqes','Hide header and footer' => 'Fshih kokën dhe fundin e faqes','Page preview' => 'Pamja paraprake e faqes','Preview viewport' => 'Parapamje paraprake','Tablet' => 'Tabletë','Desktop' => 'Desktop','Preview width' => 'Gjerësia e pamjes paraprake','Decrease width' => 'Zvogëlo gjerësinë','Preview width in pixels' => 'Gjerësia e pamjes paraprake në piksel','Increase width' => 'Rrit gjerësinë','Preview as' => 'Shiko paraprakisht si','Guest' => 'Mysafir','Logged in' => 'I kyçur','Preview page' => 'Faqja paraprake','Expand preview for a closer look' => 'Zgjero pamjen paraprake për një pamje më nga afër','Available with %s.' => 'I disponueshëm me %s.','Turn them on' => 'Ndizini ato','Optimizations for this page are turned off. %s to preview the page.' => 'Optimizimet për këtë faqe janë çaktivizuar. %s për të parë paraprakisht faqen.','%s preview' => 'Pamje paraprake e %s','Isolated session · nothing is saved' => 'Seancë e izoluar · asgjë nuk është ruajtur','Usage tracking' => 'Gjurmimi i përdorimit','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Dërgoni raporte jo të ndjeshme të mjedisit të faqes për të ndihmuar Fluid Checkout të përmirësojë përputhshmërinë. Raportet nuk dërgohen derisa të aktivizohen në opsionet më poshtë.','Send usage tracking reports to Fluid Checkout' => 'Dërgoni raportet e gjurmimit të përdorimit te Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Këto raporte na ndihmojnë të përmirësojmë përputhshmërinë dhe mbështetjen për faqen tuaj dhe dërgohen çdo javë kur aktivizohen.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Asnjë klient, përdorues administrator ose ndonjë e dhënë tjetër e ndjeshme nuk përfshihet në raporte.','Basic environment info' => 'Informacion bazë për mjedisin','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Të dhënat e WordPress, PHP, WooCommerce, temave dhe listës së shtojcave. Përfshihen gjithmonë kur raportimi është i aktivizuar. Na ndihmon të kuptojmë mjedisin në të cilin po funksionon faqja juaj e internetit.','Plugin settings' => 'Cilësimet e plugin-it','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Dërgon cilësimet e plugin-it Fluid Checkout për të ndihmuar me kërkesat e mbështetjes dhe na ndihmon të kuptojmë se si po i përdorni plugin-et tona.','Coming soon' => 'Së shpejti','Sales metrics' => 'Metrikat e shitjeve','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Numri i porosive mujore dhe shitjet totale për një vit para instalimit të Fluid Checkout deri më sot. Na ndihmon të kuptojmë nëse po fitoni më shumë para me plugin-et tona të instaluara. Nuk dërgohen kurrë të dhëna të klientëve ose përdoruesve.','Utilities' => 'Shërbimet','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Përdorni komponentët e listës zbritëse <code>TomSelect</code> në vend të <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect është një komponent përzgjedhjeje me zbritje më i thjeshtë i cili është më pak i prirur ndaj gabimeve sesa Select2, ndërsa ofron të njëjtin funksionalitet.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Cakton madhësinë e shkronjave brenda fushave të formularit në 16px në faqet e optimizuara nga ky plugin për të shmangur zmadhimin automatik gjatë bashkëveprimit me fushat e formularit në pajisje të vogla.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari dhe shfletues të tjerë mund të zmadhojnë automatikisht në pajisjet mobile për ta bërë tekstin më të lehtë për t’u lexuar kur madhësia e shkronjave është më e vogël se 16 piksel.','Enable script processing tracking on the browser console.' => 'Aktivizo gjurmimin e përpunimit të skripteve në konsolën e shfletuesit.','Unminified assets' => 'Asete të paminifikuara','Google Maps scripts' => 'Skriptet e Hartave Google','Do not remove duplicate Google Maps scripts' => 'Mos i hiqni skriptet e dyfishta të Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kur aktivizohet, skriptet e dyfishta të Google Maps NUK do të hiqen, gjë që mund të shkaktojë gabime dhe probleme me performancën. Përdoreni këtë opsion vetëm gjatë zgjidhjes së problemeve.','Widget areas' => 'Zonat e widget-eve','Last step on mobile' => 'Hapi i fundit në celular','Display widgets only at last step on mobile' => 'Shfaq widget-et vetëm në hapin e fundit në celular','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Shfaq veglat e distinktivit të besimit të arkëtimit vetëm kur shikon hapin e fundit të arkëtimit në pajisjet mobile','Standard' => 'Standard','VAT number field' => 'Fusha e numrit të TVSH-së','Add a VAT number field to the billing form.' => 'Shto një fushë të numrit të TVSH-së në formularin e faturimit.','Field label' => 'Etiketa e fushës','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Vendosni etiketën e fushës së numrit të TVSH-së (p.sh., numrin e TVSH-së). Në faqet e internetit shumëgjuhëshe, është më mirë ta lini këtë fushë bosh dhe të përktheni vargun origjinal.','VAT Number' => 'Numri i TVSH-së','EU-VAT' => 'TVSH-ja e BE-së','Enable the VAT number field to see more options' => 'Aktivizoni fushën e numrit të TVSH-së për të parë më shumë opsione','VAT validation' => 'Vlefshmëria e TVSH-së','Validate VAT number field for EU-VAT during checkout' => 'Validoni fushën e numrit të TVSH-së për TVSH-në e BE-së gjatë arkëtimit','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Kontrollon nëse Numri i TVSH-së i dhënë është një numër i vlefshëm i TVSH-së i regjistruar në Bazën e të Dhënave Evropiane VIES (Sistemi i Shkëmbimit të Informacionit për TVSH-në).','Shop VAT number' => 'Numri i TVSH-së së dyqanit','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Numri i TVSH-së i dyqanit i përdorur për të kërkuar validimin e TVSH-së së BE-së dhe i shtypur në fatura.<br> <strong>Ne ju rekomandojmë fuqimisht të shtoni numrin tuaj të TVSH-së në dyqan</strong> , pasi përndryshe rezultatet e konsultimit VIES mund të mos jenë të vlefshme për qëllime kontabiliteti.<br> Dmth.: <code>ATU99999999</code> ose <code>EE999999999</code> .','Reverse charge' => 'Ngarkim i kundërt','Apply reverse charge mechanism' => 'Zbatoni mekanizmin e ngarkesës së kundërt','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Vendosni normën e taksës në zero dhe shfaqni &quot;Faturën e kundërt&quot; në fatura kur numri i TVSH-së së klientit është i vlefshëm. Mund të kërkohet një tekst i ndryshëm &quot;Faturën e kundërt&quot; në varësi të vendit të dyqanit.','Same country' => 'I njëjti vend','Apply reverse charge mechanism for transactions in the shop country:' => 'Zbatoni mekanizmin e pagesës së kundërt për transaksionet në vendin e dyqanit:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Mundëson zbatimin e mekanizmit të ngarkesës së kundërt për transaksionet midis kompanive në të njëjtin vend me dyqanin.','Reverse charge exceptions' => 'Përjashtime nga ana e tarifës së kundërt','Select additional countries to skip applying the reverse charge mechanism.' => 'Zgjidhni vende të tjera për të anashkaluar zbatimin e mekanizmit të tarifës së kundërt.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Tatimet do të ngarkohen për porositë nga këto vende edhe kur jepet një numër i vlefshëm i TVSH-së.','Reverse charge label on invoices' => 'Etiketë e faturimit të kundërt në fatura','Set the label of "reverse charge" on the checkout page and order details.' => 'Vendosni etiketën &quot;ngarkesë e kundërt&quot; në faqen e pagesës dhe detajet e porosisë.','Reverse charge text on invoices' => 'Teksti i faturimit të kundërt në fatura','Set the label of "reverse charge" text on invoices.' => 'Vendos etiketën e tekstit &quot;ngarkesë e kundërt&quot; në fatura.','Tax to be paid on reverse charge basis' => 'Taksa që duhet të paguhet në bazë të ngarkesës së kundërt','Company name' => 'Emri i kompanisë','Autocomplete company name from VAT number' => 'Plotësoni automatikisht emrin e kompanisë nga numri i TVSH-së','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Plotësoni emrin e kompanisë faturuese bazuar në numrin e vlefshëm të TVSH-së të dhënë nga klienti.','Company name editing' => 'Redaktimi i emrit të kompanisë','Allow editing of auto-filled company name' => 'Lejo redaktimin e emrit të kompanisë të plotësuar automatikisht','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kur aktivizohet, klientët mund të ndryshojnë emrin e kompanisë të lidhur me numrin e dhënë të TVSH-së.','EU-VAT for digital goods' => 'TVSH-ja e BE-së për mallrat dixhitale','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Që nga 1 janari 2015, janë bërë ndryshime në rregulloret e TVSH-së të BE-së në lidhje me mallrat dixhitale, të cilat ndikojnë ekskluzivisht në transaksionet B2C. TVSH-ja për mallrat dixhitale duhet të llogaritet bazuar në vendndodhjen e klientit dhe duhet të mblidhen prova për këtë (adresa IP dhe adresa e faturimit).','Tax classes for digital goods' => 'Klasat tatimore për mallrat dixhitale','Select some tax classes' => 'Zgjidhni disa klasa tatimore','Location evidence' => 'Provat e vendndodhjes','Collect customer\'s location evidence' => 'Mbledh provat e vendndodhjes së klientit','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Ruan adresën IP dhe e krahason atë me adresën e faturimit të klientit. Klienti duhet të konfirmojë adresën e tij të faturimit duke zgjedhur një kuti kontrolli në faqen e pagesës nëse vendi nga adresa e tij e faturimit dhe IP-ja nuk përputhen.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ky opsion menaxhohet në Fluid Checkout. <a href="%s">Ndryshojeni atë në cilësimet e llogarive të klientëve</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ky opsion menaxhohet në Fluid Checkout. Ndryshojeni atë te Fluid Checkout &gt; Llogaritë e klientëve.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ky opsion menaxhohet në Fluid Checkout. Destinacioni i dërgesës është gjithmonë i vendosur në &quot;Adresa e dërgesës së klientit si parazgjedhje&quot; kur aktivizohet Fluid Checkout. Klientët ende mund të japin adresa të ndryshme dërgesash dhe faturimi gjatë përfundimit të pagesës.<br><br> Një opsion për të vendosur adresën e parazgjedhur të faturimit në të njëjtën mënyrë si adresa e dërgesës është i disponueshëm në <a href="%s">cilësimet e Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ky opsion menaxhohet në Fluid Checkout. Destinacioni i dërgesës është gjithmonë i vendosur në &quot;Adresa e dërgesës së klientit si parazgjedhje&quot; kur aktivizohet Fluid Checkout. Klientët ende mund të japin adresa të ndryshme dërgesash dhe faturimi gjatë përfundimit të pagesës.<br><br> Një opsion për të vendosur adresën e parazgjedhur të faturimit në të njëjtën mënyrë si adresa e dërgesës është i disponueshëm te WooCommerce &gt; Cilësimet &gt; Pagesa Fluide.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Këto cilësime janë zhvendosur te WP Admin &gt; Fluid Checkout &gt; Settings.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Kjo skedë e Cilësimeve të WooCommerce është e vjetruar dhe do të hiqet në Fluid Checkout 6.0.','Go to settings page' => 'Shko te faqja e cilësimeve','Hide this tab permanently' => 'Fshihe këtë skedë përgjithmonë','Site report preview' => 'Pamje paraprake e raportit të faqes','This is the data that would be included in the next site environment report based on your current settings.' => 'Këto janë të dhënat që do të përfshihen në raportin tjetër të mjedisit të faqes bazuar në cilësimet tuaja aktuale.','Loading report preview...' => 'Duke ngarkuar pamjen paraprake të raportit...','Could not load the site report preview. Try again.' => 'Nuk mund të ngarkohej pamja paraprake e raportit të faqes. Provo përsëri.','Could not send the site report. Try again.' => 'Raporti i faqes nuk mund të dërgohej. Provo përsëri.','Site report sent successfully.' => 'Raporti i faqes u dërgua me sukses.','Enable and send now' => 'Aktivizo dhe dërgo tani','Close' => 'Mbyll','A site report request is already in progress. Try again in a moment.' => 'Një kërkesë për raportimin e faqes është tashmë në proces. Provo përsëri pas pak.','Site environment reporting is disabled.' => 'Raportimi i mjedisit të faqes është çaktivizuar.','No site report data is available to send.' => 'Nuk ka të dhëna raporti të faqes për t&#39;u dërguar.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ky domen i faqes nuk mund të dërgojë raporte mjedisore (përjashtohen domenet lokale ose të zhvillimit).','A site report was sent recently. Try again later.' => 'Një raport për faqen u dërgua së fundmi. Provo përsëri më vonë.','The site report could not be sent. Try again later.' => 'Raporti i faqes nuk mund të dërgohej. Provo përsëri më vonë.','Site environment reporting is not available.' => 'Raportimi i mjedisit të faqes nuk është i disponueshëm.','No site report data is available for the selected settings.' => 'Nuk ka të dhëna të raportit të faqes në dispozicion për cilësimet e zgjedhura.','You are not allowed to manage site reports.' => 'Nuk lejoheni të menaxhoni raportet e faqes.','PRO feature' => 'Funksioni PRO','Other plugins' => 'Plugin-e të tjera','Get only this add-on &mdash; %s' => 'Merr vetëm këtë shtesë — %s','Install add-on' => 'Instalo shtesën','Upgrade to PRO &mdash; %s' => 'Përmirëso në PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Merr %2$s</a> për të zhbllokuar këto opsione.','Add-on' => 'Shtesë','View documentation' => 'Shiko dokumentacionin','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Kërkesat kërkojnë një përdorues të WordPress të kyçur. Hiqni user_id për të përdorur të dhënat e përdoruesit aktual, ose kaloni user_id për të synuar një llogari tjetër kur thirrësi mund ta modifikojë atë përdorues (aftësia edit_user). Kërkesat e paautorizuara kthejnë fc_api_forbidden. Një user_id i pavlefshëm kthen fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 me { &quot;të dhëna&quot;: { ... } } kur trajtuesi kthen një ngarkesë.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 me { &quot;success&quot;: true } kur nuk ka ngarkesë (për shembull DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Dështimet kthejnë gabimin REST të WordPress në formatin JSON nga WP_Error (kod, mesazh, data.status). Kodet e telave përdorin parashtesën fc_api_*.','Forbidden access.' => 'Qasje e ndaluar.','Target user was not found.' => 'Përdoruesi i synuar nuk u gjet.','This feature is not available.' => 'Kjo veçori nuk është e disponueshme.','A required address field is missing.' => 'Mungon një fushë e detyrueshme adrese.','Postcode or ZIP is invalid.' => 'Kodi postar ose kodi postar është i pavlefshëm.','Phone number is invalid.' => 'Numri i telefonit është i pavlefshëm.','State or county is invalid.' => 'Shteti ose qarku është i pavlefshëm.','Country is invalid or has no address fields.' => 'Vendi është i pavlefshëm ose nuk ka fusha adrese.','The request could not be processed.' => 'Kërkesa nuk mund të përpunohej.','Back to previous step' => 'Kthehu te hapi i mëparshëm','Skip to settings' => 'Kapërce te cilësimet','Start over and return to the first guided setup step' => 'Filloni nga e para dhe kthehuni te hapi i parë i konfigurimit me udhëzime','Start over' => 'Fillo nga e para','Please complete all sub-steps before continuing.' => 'Ju lutemi plotësoni të gjitha nën-hapat përpara se të vazhdoni.','Expand' => 'Zgjero','Collapse' => 'Palos','Skip' => 'Kapërce','Mark as complete' => 'Shëno si të përfunduar','Mark as incomplete' => 'Shëno si të papërfunduar','View full-size image: %s' => 'Shiko imazhin në madhësi të plotë: %s','Full-size setup guide image' => 'Imazh udhëzues konfigurimi në madhësi të plotë','Close image' => 'Mbyll imazhin','Fluid Checkout Guided Setup' => 'Konfigurimi i Udhëzuar i Kontrollit të Lëngjeve','Welcome' => 'Mirë se vini','Explore your checkout' => 'Eksploroni arkëtimin tuaj','All set' => 'Gati','You do not have permission to access this page.' => 'Ju nuk keni leje për të hyrë në këtë faqe.','Go to step %1$d: %2$s' => 'Shko te hapi %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ky konfigurim i udhëzuar ju ndihmon të njiheni me Fluid Checkout. Hapat më poshtë janë zëvendësues për momentin.','Continue to the next step when you are ready.' => 'Vazhdoni në hapin tjetër kur të jeni gati.','Open your store checkout to see Fluid Checkout in action.' => 'Hapni arkën e dyqanit tuaj për të parë Fluid Checkout në veprim.','View checkout page' => 'Shiko faqen e pagesës','You can return to Fluid Checkout settings to continue configuring your store.' => 'Mund të ktheheni te cilësimet e Fluid Checkout për të vazhduar konfigurimin e dyqanit tuaj.','Review checkout and cart settings' => 'Rishikoni cilësimet e arkëtimit dhe të shportës','Explore add-ons from the dashboard' => 'Eksploroni shtesat nga paneli','Finish & go to settings' => 'Përfundo dhe shko te cilësimet','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Përditësoni opsionin e dukshmërisë së fushës së telefonit të faturimit nga vlera e trashëguar për t&#39;u përputhur me konventat e WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Përditësoni opsionin e dukshmërisë së fushës së telefonit të dërgesës nga vlera e trashëguar për t&#39;u përputhur me konventat e WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopjoni cilësimin e ngjyrës së sfondit të përmbledhjes së porosisë në opsionin e ri të ngjyrës së sfondit të kolonës dytësore të dizajnit të ndarë.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Funksioni i fushave të zgjeruara të përzgjedhjes është gjithmonë i çaktivizuar kur përdorni shtojcën Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pozicioni i vendosjes së porosisë është gjithmonë i vendosur në &quot;Nën përmbledhjen e porosisë&quot; kur përdorni Tregun Gjerman. Ky plugin kërkon që butoni i vendosjes së porosisë dhe kutitë ligjore të shfaqen poshtë përmbledhjes së porosisë.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pozicioni i vendosjes së porosisë është gjithmonë i vendosur në &quot;Nën përmbledhjen e porosisë&quot; kur përdoret Germanized for WooCommerce. Ky plugin kërkon që butoni i vendosjes së porosisë dhe kutitë e kontrollit ligjore të shfaqen poshtë përmbledhjes së porosisë.','Edit pickup locations' => 'Modifiko vendet e marrjes','Use local pickup label from WooCommerce settings' => 'Përdorni etiketën lokale të marrjes nga cilësimet e WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kur aktivizohet, etiketa e opsionit të marrjes në arkë përputhet me titullin nga cilësimet e vendndodhjes së marrjes në WooCommerce. Kur çaktivizohet, etiketa përdor tekstin e përkthyeshëm &quot;Marrje lokale&quot; nga Fluid Checkout.','Button label for applying coupon codesApply' => 'Aplikoni','Checkout step titleContact' => 'Kontaktoni','Checkout step titleShipping' => 'Transporti','Checkout step titleBilling' => 'Faturimi','Checkout step titlePayment' => 'Pagesa','Checkout substep change link labelChange' => 'Ndryshimi','Checkout substep save link labelSave changes' => 'Ruaj ndryshimet','Substep review textNone.' => 'Asnjë.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Asnjë imazh i zgjedhur.','Settings sectionCart' => 'Karrocë','Settings sectionOrder pay' => 'Urdhëroni pagesën','Settings sectionThank you' => 'faleminderit','Settings section titleIntegrations' => 'Integrimet','Settings section titleLicense keys' => 'Çelësat e licencës','Captcha positionBefore place order section' => 'Para seksionit të porosisë','Captcha positionBefore place order button' => 'Butoni para vendosjes së porosisë','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Mbylle','Log in link label at checkout contact stepLog in' => 'Identifikohu','Log in separator label at for when guest checkout is disabledOr continue below' => 'Ose vazhdoni më poshtë','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Ose vazhdoni si mysafir','Clear image selection on admin pages.Remove image' => 'Hiq imazhin','shipping packagesShipping %d' => 'Transporti %d','shipping packagesShipping' => 'Transporti','Used as fallback for "Proceed to next step" button labelnext step' => 'hapi tjetër','Substep review checkbox valueYes' => 'Po','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin 